const phases=[['beginning','Upkeep · draw next'],['precombat_main','Main 1'],['combat','Combat'],['postcombat_main','Main 2'],['ending','End turn']]
function ZoneCard({card,legal,onClick,attacking=false,blocked=false,selected=false,entering=false}:{card:GameCard;legal?:boolean;onClick?:()=>void;attacking?:boolean;blocked?:boolean;selected?:boolean;entering?:boolean}){
  const faceDown=(card as GameCard&{face_down?:boolean}).face_down
  return <Tooltip title={<><b>{card.name}</b><br/>{card.type_line}{card.effective_power!==undefined&&<><br/><b>{card.effective_power}/{card.effective_toughness}</b></>}<br/>{card.oracle_text}</>} placement="top" arrow>
    <Box className={`play-card ${card.tapped?'is-tapped':''} ${legal?'is-legal':''} ${attacking?'is-attacking':''} ${selected?'is-selected':''} ${entering?'is-entering':''}`} onClick={onClick} role={legal?'button':undefined} aria-label={card.name}>
      {faceDown?<Box className="card-back manifest-card-back"/>:card.image_url?<Box component="img" src={card.image_url} alt={card.name}/>:<Box className="token-face"><AutoAwesome/><Typography fontWeight={900}>{card.name}</Typography><Typography variant="caption">{card.type_line}</Typography></Box>}
      {(card.damage>0||Object.values(card.counters||{}).some(Boolean)||!!card.regeneration_shields)&&<Chip className="play-counter" size="small" color={card.damage?'error':'success'} label={card.damage?`${card.damage} dmg`:card.regeneration_shields?`↻ ${card.regeneration_shields} regen`:Object.entries(card.counters).filter(([,amount])=>amount).map(([name,amount])=>`${amount} ${name}`).join(', ')}/>} {card.effective_power!==undefined&&<Chip className="play-stats" size="small" label={`${card.effective_power}/${card.effective_toughness}`}/>} {card.mutate_pile&&<Tooltip title={`Merged cards: ${card.mutate_pile.map(item=>item.name).join(', ')}`}><Chip className="play-attached" size="small" color="secondary" label={`Mutated ×${card.mutate_count||1}`}/></Tooltip>} {card.attached_to&&<Chip className="play-attached" size="small" color="info" label="Attached"/>} {blocked&&<Chip className="play-blocked" size="small" label="Blocked"/>}
    </Box>
  </Tooltip>
}

function HiddenHand({count=0}:{count?:number}){return <Stack direction="row" justifyContent="center" className="hidden-hand">{Array.from({length:Math.min(count,12)},(_,index)=><Box key={index} className="card-back" sx={{ml:index?-4:0}}/>)}</Stack>}

function CommanderDamage({player}:{player?:GamePlayer}){return <>{!!player?.energy&&<Tooltip title={`${player.energy_paid_this_turn||0} energy paid this turn`}><Chip size="small" color="info" label={`⚡ ${player.energy} energy`}/></Tooltip>}{!!player?.rad&&<Tooltip title="Rad triggers at the beginning of precombat main"><Chip size="small" color="warning" label={`☢ ${player.rad} rad`}/></Tooltip>}{!!player?.experience&&<Chip size="small" color="secondary" label={`★ ${player.experience} experience`}/>} {!!player?.speed&&<Tooltip title={player.speed>=4?'Max speed reached':'Speed increases once each of your turns when an opponent loses life'}><Chip size="small" color={player.speed>=4?'success':'warning'} label={`🏁 speed ${player.speed}${player.speed>=4?' · MAX':''}`}/></Tooltip>} {!!player?.any_color_mana&&<Tooltip title="Floating mana empties when the current phase ends"><Chip size="small" color="secondary" icon={<Bolt/>} label={`${player.any_color_mana} floating mana`}/></Tooltip>}{commanderDamageTotals(player).map(total=><Tooltip key={total.id} title={`${total.name} has dealt ${total.amount} of the 21 combat damage needed to win`}><Chip size="small" color={total.amount>=18?'error':'warning'} label={`⚔ ${total.name} ${total.amount}/21`}/></Tooltip>)}</>}

function Battlefield({player,game,onCard,selectableIds=new Set(),selectedIds=new Set(),enteringIds=new Set(),onSelect}:{player:GamePlayer;game:Game;onCard:(card:GameCard)=>void;selectableIds?:Set<string>;selectedIds?:Set<string>;enteringIds?:Set<string>;onSelect?:(card:GameCard)=>void}){
  const attackers=new Set(game.state.combat.attackers),blocked=new Set(Object.values(game.state.combat.blocks))
  const creatures=player.battlefield.filter(card=>!card.type_line.includes('Land')),lands=player.battlefield.filter(card=>card.type_line.includes('Land'))
  return <Box className="battlefield-zone">
    <Stack direction="row" className="permanent-row" justifyContent="center">{creatures.map(card=>{const selectable=selectableIds.has(card.instance_id),legal=selectable||game.legal_actions.some(action=>action.card_id===card.instance_id);return <ZoneCard key={card.instance_id} card={card} legal={legal} selected={selectedIds.has(card.instance_id)} entering={enteringIds.has(card.instance_id)} onClick={()=>selectable&&onSelect?onSelect(card):onCard(card)} attacking={attackers.has(card.instance_id)} blocked={blocked.has(card.instance_id)}/>})}</Stack>
    <Stack direction="row" className="land-row" justifyContent="center">{lands.map(card=>{const legal=game.legal_actions.some(action=>action.card_id===card.instance_id);return <ZoneCard key={card.instance_id} card={card} legal={legal} entering={enteringIds.has(card.instance_id)} onClick={()=>onCard(card)}/>})}</Stack>
  </Box>
}

