    <Dialog open={!!blockOrderAction} fullWidth maxWidth="md" disableEscapeKeyDown><DialogTitle>Order combat damage</DialogTitle><DialogContent><Alert severity="info" sx={{mb:2}}>Your attacker deals lethal damage to each blocker in this order before assigning damage to the next.</Alert><Stack spacing={3}>{blockOrderAction?.groups?.map(group=>{const defaults=group.blockers.map(card=>card.instance_id),order=blockOrders[group.attacker.instance_id]||defaults;return <Box key={group.attacker.instance_id}><Typography fontWeight={900} mb={1}>{group.attacker.name} ({group.attacker.power}/{group.attacker.toughness})</Typography><Stack direction="row" gap={1.5} flexWrap="wrap">{order.map((id,index)=>{const blocker=group.blockers.find(card=>card.instance_id===id)!;return <Paper key={id} variant="outlined" sx={{width:140,p:1}}><Box component="img" src={blocker.image_url||''} alt={blocker.name} sx={{width:'100%',aspectRatio:'488 / 680',objectFit:'cover',display:'block'}}/><Typography fontWeight={800} noWrap mt={.75}>{index+1}. {blocker.name}</Typography><Typography variant="caption">{blocker.power}/{blocker.toughness}</Typography><Stack direction="row" justifyContent="space-between"><IconButton size="small" disabled={index===0} onClick={()=>moveBlocker(group.attacker.instance_id,defaults,index,-1)}><ArrowUpward/></IconButton><IconButton size="small" disabled={index===order.length-1} onClick={()=>moveBlocker(group.attacker.instance_id,defaults,index,1)}><ArrowDownward/></IconButton></Stack></Paper>})}</Stack></Box>})}</Stack></DialogContent><DialogActions><Button variant="contained" disabled={busy} onClick={()=>void act({type:'order_blockers',block_orders:Object.fromEntries((blockOrderAction?.groups||[]).map(group=>[group.attacker.instance_id,blockOrders[group.attacker.instance_id]||group.blockers.map(card=>card.instance_id)]))})}>Assign damage</Button></DialogActions></Dialog>
